  'junior-site-engineer',
  'Junior Site Engineer',
  'Civil Engineering',
  'Keeps real-world execution aligned by combining site setting out and surveying, construction drawing interpretation, and practical troubleshooting.',
  'A junior in this role is likely to spend time on site setting out and surveying, construction drawing interpretation, and concrete mix design and testing. As responsibility grows, reinforcement detailing basics becomes part of the routine.',
  'The role catches the gap between the plan and what is actually happening. site setting out and surveying and construction drawing interpretation help keep work safe, traceable, and within spec.',
  25,
  '["site setting out and surveying","construction drawing interpretation","concrete mix design and testing","reinforcement detailing basics","site measurement and recording","quality inspection at site","construction progress monitoring","safety inspection at site"]',
  'Prepare a mini site-execution pack for a small project: setting-out notes, drawing checks, quantity/progress records, a quality checklist, and a short site-risk log.',
  'inspection or maintenance sheet; measurements; issue log; handover note',
  'Start with site setting out and surveying. Move into construction drawing interpretation and concrete mix design and testing, then use reinforcement detailing basics inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
  'Explore the Junior Site Engineer path',
  'site setting out and surveying',
  'Construction Surveying',
  '',
  'Civil Engineers',
  'https://www.onetonline.org/link/summary/17-2051.00',
  'Junior Site Engineer Career Roadmap: Skills, Projects & Proof | Pathwisse',
  'Keeps real-world execution aligned by combining site setting out and surveying, construction drawing interpretation, and practical troublesh Understand daily re',
  '[["What does a Junior Site Engineer actually do on a day-to-day basis?","A junior in this role is likely to spend time on site setting out and surveying, construction drawing interpretation, and concrete mix design and testing. As responsibility grows, reinforcement detailing basics becomes part of the routine."],["What problems does a Junior Site Engineer solve?","The role catches the gap between the plan and what is actually happening. site setting out and surveying and construction drawing interpretation help keep work safe, traceable, and within spec."],["How do I build verifiable proof for a Junior Site Engineer role without prior experience?","Pathwisse recommends starting with: Start with site setting out and surveying. Move into construction drawing interpretation and concrete mix design and testing, then use reinforcement detailing basics inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete. Build out the \"Prepare a mini site-execution pack for a small project: setting-out notes, drawing checks, quantity/progress records, a quality checklist, and a short site-risk log.\" capstone project and showcase verifiable evidence such as: inspection or maintenance sheet; measurements; issue log; handover note."],["Is the Junior Site Engineer roadmap free to try on Pathwisse?","Yes, the Junior Site Engineer career direction diagnostic, skill breakdown, and foundation project blueprints are completely free to try."]]'
);
