  'cad-draftsman-civil',
  'CAD Draftsman (Civil)',
  'Civil Engineering',
  'Turns a requirement into buildable detail through 2d drafting and 3d cad modeling.',
  'Early assignments are usually concrete: 2d drafting and 3d cad modeling first, then more ownership around drawing coordination.',
  'The role removes ambiguity before execution. 2d drafting and 3d cad modeling turn an idea into dimensions, models, drawings, calculations, or specifications another team can trust.',
  25,
  '["2d drafting","3d cad modeling","drawing coordination","as-built drawing preparation","drawing revision management","layer management in cad","title block and annotation standards","drawing extraction and plotting"]',
  'Create a complete design pack around 2d drafting: requirements, calculations or model, drawings, checks, and a short design-review note.',
  'requirements; calculation/model; drawing/design file; review checklist',
  'Start with 2d drafting. Move into 3d cad modeling and drawing coordination, then use as-built drawing preparation inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
