  'junior-quantity-surveyor',
  'Junior Quantity Surveyor',
  'Civil Engineering',
  'Turns bill of quantities preparation into a decision people can act on, then pressure-tests it with rate analysis.',
  'Most learning happens through outputs someone else can review. Expect work involving bill of quantities preparation, rate analysis, material takeoff, and cost estimation for construction rather than only theory.',
  'The role reduces guesswork. bill of quantities preparation and rate analysis make patterns, exceptions, and trade-offs visible enough for someone to choose a direction.',
  25,
  '["bill of quantities preparation","rate analysis","material takeoff","cost estimation for construction","tender documentation preparation","contract administration basics","variation order management","construction progress billing"]',
  'Build a complete estimate from a sample drawing set: quantity take-off, BOQ, rate analysis, assumptions, and a short variance note when scope changes.',
  'working file or notebook; calculation/query trail; visual/model; decision memo',
  'Start with bill of quantities preparation. Move into rate analysis and material takeoff, then use cost estimation for construction inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
  'Explore the Junior Quantity Surveyor path',
  'bill of quantities preparation',
  'Bill of Quantities Preparation',
  '',
  'Civil Engineers',
  'https://www.onetonline.org/link/summary/17-2051.00',
  'Junior Quantity Surveyor Career Roadmap: Skills, Projects & Proof | Pathwisse',
  'Turns bill of quantities preparation into a decision people can act on, then pressure-tests it with rate analysis. Understand daily responsibilities, required s',
  '[["What does a Junior Quantity Surveyor actually do on a day-to-day basis?","Most learning happens through outputs someone else can review. Expect work involving bill of quantities preparation, rate analysis, material takeoff, and cost estimation for construction rather than only theory."],["What problems does a Junior Quantity Surveyor solve?","The role reduces guesswork. bill of quantities preparation and rate analysis make patterns, exceptions, and trade-offs visible enough for someone to choose a direction."],["How do I build verifiable proof for a Junior Quantity Surveyor role without prior experience?","Pathwisse recommends starting with: Start with bill of quantities preparation. Move into rate analysis and material takeoff, then use cost estimation for construction inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete. Build out the \"Build a complete estimate from a sample drawing set: quantity take-off, BOQ, rate analysis, assumptions, and a short variance note when scope changes.\" capstone project and showcase verifiable evidence such as: working file or notebook; calculation/query trail; visual/model; decision memo."],["Is the Junior Quantity Surveyor roadmap free to try on Pathwisse?","Yes, the Junior Quantity Surveyor career direction diagnostic, skill breakdown, and foundation project blueprints are completely free to try."]]'
);
