  'energy-audit-trainee',
  'Energy Audit Trainee',
  'Electrical Engineering',
  'Uses energy consumption data collection and electrical load survey to catch problems before they travel further into the system or process.',
  'Most learning happens through outputs someone else can review. Expect work involving energy consumption data collection, electrical load survey, power quality monitoring, and energy baseline calculation rather than only theory.',
  'The role exists to stop weak work from being accepted as good work. energy consumption data collection and electrical load survey help expose defects, missed controls, unsafe conditions, or gaps that need correction.',
  24,
  '["energy consumption data collection","electrical load survey","power quality monitoring","energy baseline calculation","lighting audit techniques","hvac energy analysis","motor efficiency assessment","energy saving opportunity identification"]',
  'Run a realistic energy consumption data collection review on a sample system or process. Log the evidence, findings, root cause, corrective action, and how you verified the fix.',
  'test/check plan; findings log; root-cause note; corrective-action evidence',
  'Start with energy consumption data collection. Move into electrical load survey and power quality monitoring, then use energy baseline calculation inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
