  'graduate-process-engineer-trainee',
  'Graduate Process Engineer Trainee',
  'Chemical Engineering',
  'Makes production more repeatable by improving process flow diagram preparation and mass and energy balance calculations without losing sight of output.',
  'A junior in this role is likely to spend time on process flow diagram preparation, mass and energy balance calculations, and process simulation. As responsibility grows, piping and instrumentation diagram interpretation becomes part of the routine.',
  'The role removes avoidable variation. process flow diagram preparation and mass and energy balance calculations are used to cut repeat failures, delays, rework, and unstable output.',
  25,
  '["process flow diagram preparation","mass and energy balance calculations","process simulation","piping and instrumentation diagram interpretation","heat exchanger design basics","pump and compressor sizing","process equipment selection","unit operations fundamentals"]',
  'Map a sample process, measure where it loses time or quality, improve one step using process flow diagram preparation, and show the before/after evidence.',
  'process map; baseline metrics; improvement record; before/after result',
  'Start with process flow diagram preparation. Move into mass and energy balance calculations and process simulation, then use piping and instrumentation diagram interpretation inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
