  'junior-quality-control-chemist',
  'Junior Quality Control Chemist',
  'Chemical Engineering',
  'Uses wet chemical analysis and instrumental analysis techniques to catch problems before they travel further into the system or process.',
  'Early assignments are usually concrete: wet chemical analysis and instrumental analysis techniques first, then more ownership around hplc analysis.',
  'The role exists to stop weak work from being accepted as good work. wet chemical analysis and instrumental analysis techniques help expose defects, missed controls, unsafe conditions, or gaps that need correction.',
  25,
  '["wet chemical analysis","instrumental analysis techniques","hplc analysis","gc analysis","titration methods","spectroscopic analysis","sampling and sample preparation","batch record review"]',
  'Run a realistic wet chemical analysis review on a sample system or process. Log the evidence, findings, root cause, corrective action, and how you verified the fix.',
  'test/check plan; findings log; root-cause note; corrective-action evidence',
  'Start with wet chemical analysis. Move into instrumental analysis techniques and hplc analysis, then use gc analysis inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
