  'The role turns an open technical question into a testable one. synthesis route development and analytical method development matter because the conclusion has to survive review.',
  25,
  '["synthesis route development","analytical method development","reaction optimization","scale-up study basics","experimental design","literature review and synthesis","lab notebook documentation","spectroscopic analysis"]',
  'Design a small experiment around synthesis route development, document the method, capture results, discuss uncertainty, and turn the conclusion into an engineering recommendation.',
