  'quality-engineer-medical-devices',
  'Quality Engineer (Medical Devices)',
  'Biomedical Engineering',
  'Uses quality management system implementation and design control procedures to catch problems before they travel further into the system or process.',
  'A junior in this role is likely to spend time on quality management system implementation, design control procedures, and production process validation. As responsibility grows, incoming inspection procedures becomes part of the routine.',
  'The role exists to stop weak work from being accepted as good work. quality management system implementation and design control procedures help expose defects, missed controls, unsafe conditions, or gaps that need correction.',
  25,
  '["quality management system implementation","design control procedures","production process validation","incoming inspection procedures","non-conformance management","corrective and preventive action","statistical process control","risk management documentation"]',
  'Run a realistic quality management system implementation review on a sample system or process. Log the evidence, findings, root cause, corrective action, and how you verified the fix.',
  'test/check plan; findings log; root-cause note; corrective-action evidence',
  'Start with quality management system implementation. Move into design control procedures and production process validation, then use incoming inspection procedures inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
