  'Uses quality management system implementation and design control procedures to catch problems before they travel further into the system or  Understand daily re',
  '[["What does a Quality Engineer (Medical Devices) actually do on a day-to-day basis?","A junior in this role is likely to spend time on quality management system implementation, design control procedures, and production process validation. As responsibility grows, incoming inspection procedures becomes part of the routine."],["What problems does a Quality Engineer (Medical Devices) solve?","The role exists to stop weak work from being accepted as good work. quality management system implementation and design control procedures help expose defects, missed controls, unsafe conditions, or gaps that need correction."],["How do I build verifiable proof for a Quality Engineer (Medical Devices) role without prior experience?","Pathwisse recommends starting with: Start with quality management system implementation. Move into design control procedures and production process validation, then use incoming inspection procedures inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete. Build out the \"Run a realistic quality management system implementation review on a sample system or process. Log the evidence, findings, root cause, corrective action, and how you verified the fix.\" capstone project and showcase verifiable evidence such as: test/check plan; findings log; root-cause note; corrective-action evidence."],["Is the Quality Engineer (Medical Devices) roadmap free to try on Pathwisse?","Yes, the Quality Engineer (Medical Devices) career direction diagnostic, skill breakdown, and foundation project blueprints are completely free to try."]]'
