  'biomechanics-research-trainee',
  'Biomechanics Research Trainee',
  'Biomedical Engineering',
  'Uses biomechanical data collection and motion capture analysis to answer a technical question with evidence rather than opinion.',
  'Most learning happens through outputs someone else can review. Expect work involving biomechanical data collection, motion capture analysis, force plate data analysis, and emg signal analysis rather than only theory.',
  'The role turns an open technical question into a testable one. biomechanical data collection and motion capture analysis matter because the conclusion has to survive review.',
  25,
  '["biomechanical data collection","motion capture analysis","force plate data analysis","emg signal analysis","musculoskeletal modeling","gait analysis","statistical analysis","experimental design"]',
  'Design a small experiment around biomechanical data collection, document the method, capture results, discuss uncertainty, and turn the conclusion into an engineering recommendation.',
  'method; data; analysis; limitations note; technical recommendation',
  'Start with biomechanical data collection. Move into motion capture analysis and force plate data analysis, then use emg signal analysis inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
