  'aerospace-quality-engineer-trainee',
  'Aerospace Quality Engineer Trainee',
  'Aerospace Engineering',
  'Uses quality audit procedures and first article inspection to catch problems before they travel further into the system or process.',
  'Early assignments are usually concrete: quality audit procedures and first article inspection first, then more ownership around non-conformance reporting.',
