  'production-planning-and-control-ppc-trainee',
  'Production Planning & Control (PPC) Trainee',
  'Industrial & Manufacturing Engg',
  'Turns scope and constraints into a workable plan using planning fundamentals and resource or cost discipline.',
  'Early assignments are usually concrete: role-specific fundamentals first, then more ownership around review and execution.',
  'The role keeps one constraint from derailing the whole plan. Planning and resource analysis are used to balance time, capacity, sequence, material, or cost.',
  15,
