  'Junior ML Engineer',
  'Computer Science Engineering',
  'Makes data or AI systems useful by combining machine learning algorithms with supervised learning and explicit quality checks.',
  'A junior in this role is likely to spend time on machine learning algorithms, supervised learning, and unsupervised learning. As responsibility grows, model training and evaluation becomes part of the routine.',
