  'The role keeps a digital workflow from failing at the seams. rest api development and database schema design are used to deal with broken logic, unreliable interfaces, performance issues, and code that is hard to change safely.',
  24,
  '["rest api development","database schema design","authentication and authorisation","microservices architecture","python","message queue integration","unit testing","server side caching"]',
  'Build and deploy a small production-style project using rest api development and database schema design. Include tests, failure handling, README, and a short demo.',
  'source code; tests; README; deployed demo or screen recording',
  'Start with rest api development. Move into database schema design and authentication and authorisation, then use microservices architecture inside a reviewable project. The next layer should unlock when the learner can show the work, not just mark a lesson complete.',
